# The Sorus client 0.3.0, generated by the client release from its files;
# copy it to sorus-run/homebrew-tap as Formula/sorus.rb.
class Sorus < Formula
  desc "Client for Sorus, which runs Rust builds and tests on remote machines"
  homepage "https://www.sorus.run"
  version "0.3.0"
  license :cannot_represent

  on_macos do
    on_arm do
      url "https://github.com/sorus-run/sorus/releases/download/v0.3.0/sorus-0.3.0-aarch64-apple-darwin"
      sha256 "f9a5a1ede3a0e73fe04929e7b4024c3dca8d9be08cc53019c85632c1e85f93b1"
    end
    on_intel do
      url "https://github.com/sorus-run/sorus/releases/download/v0.3.0/sorus-0.3.0-x86_64-apple-darwin"
      sha256 "50c5ecf381e13c83f42bcd1569b708432e9cd36a43535a39e4d2a634f3adc0c3"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/sorus-run/sorus/releases/download/v0.3.0/sorus-0.3.0-aarch64-unknown-linux-musl"
      sha256 "bbfc3a6737856d3303d2606d9e29b293fb9fc522c252ce5b5bd4efc70c988dd5"
    end
    on_intel do
      url "https://github.com/sorus-run/sorus/releases/download/v0.3.0/sorus-0.3.0-x86_64-unknown-linux-musl"
      sha256 "3fafac897ec5744c2f12d199aa7170a9062c1573be03adc5ade659d55ac67397"
    end
  end

  def install
    bin.install Dir["sorus-#{version}-*"].first => "sorus"
    bin.install_symlink "sorus" => "cargo-sorus"
  end

  test do
    assert_match "sorus #{version} (", shell_output("#{bin}/sorus --version")
  end
end
